def _field_specs_for(prefix: str, defaults: dict[str, Any], category: str = "General") -> list[dict[str, Any]]:
    specs: list[dict[str, Any]] = []
    for key, value in defaults.items():
        path = f"{prefix}.{key}" if prefix else key
        if isinstance(value, dict):
            specs.extend(_field_specs_for(path, value, category="Nested / item policy"))
            continue
        label = FIELD_LABELS.get(key, key.replace("_", " ").title())
        specs.append({
            "key": path,
            "label": label,
            "kind": _type_name(value),
            "default": copy.deepcopy(value),
            "category": category,
            "description": FIELD_DESCRIPTIONS.get(key, "Điều chỉnh tham số bot này. Tăng/giảm giá trị sẽ thay đổi mức ưu tiên tương ứng trong strategy."),
        })
    return specs


def bot_config_field_specs() -> dict[str, list[dict[str, Any]]]:
    return {
        sid: _field_specs_for("", defaults)
        for sid, defaults in DEFAULT_BOT_CONFIG["scenarios"].items()
    }
